{
  "book_code": "2ES",
  "verses": [
    {
      "text_ar": "قدِ دُنْتَ الأرْضَ، وَلَكِنْ لَيْسَ بِالْحَقِّ.",
      "chapter": 11,
      "verse": 41
    },
    {
      "text_ar": "لأنَّكَ أذْلَيْتَ الْوُدَعَاءَ، وَآذَيْتَ الْمُسَالِمِينَ، وَأبْغَضْتَ الَّذِينَ يَنْطِقُونَ بِالْحَقِّ، وَأحْبَبْتَ الْكَاذِبِينَ، وَدَمَّرْتَ مَسَاكِنَ الَّذِينَ أنْتَجُوا ثَمَراً، وَهَدَمْتَ أَسْوَارَ الَّذِينَ لَمْ يُؤْذُوكَ بِسُوءٍ.",
      "chapter": 11,
      "verse": 42
    },
    {
      "text_ar": "لَقَدْ صَعِدَتْ وَسَاحَتُكَ إلَى الْعَلِيِّ، وَكِبْرِيَاؤُكَ إلَى الْقَدِيرِ.",
      "chapter": 11,
      "verse": 43
    },
    {
      "text_ar": "وَالْعَلِيُّ أَيْضاً نَظَرَ إِلَى أَزْمِنَتِهِ، وَهُوَذَا قَدِ انْتَهَتْ، وَتَمَّتْ عُصُورُهُ.",
      "chapter": 11,
      "verse": 44
    },
    {
      "text_ar": "لِذَلِكَ لا تَظْهَرِي بَعْدُ أَيَّتُهَا النَّسْرُ، وَلا أَجْنِحَتُكِ الْمُرْعِبَةُ، وَلا أَجْنِحَتُكِ الصَّغِيرَةُ الشِّرِّيرَةُ، وَلا رُؤُوسُكِ الْقَاسِيَةُ، وَلا مَخَالِبُكِ الْمُؤْذِيَةُ، وَلا كُلُّ جَسَدِكِ الْعَدِيمُ الْفَائِدَةِ،",
      "chapter": 11,
      "verse": 45
    },
    {
      "text_ar": "لِكَيْ تَتَرَنَّحَ الأَرْضُ كُلُّهَا وَتَسْتَرِيحَ، مُتَحَرِّرَةً مِنْ عُنْفِكِ، وَلِكَيْ تَرْجُوَ قَضَاءَ وَرَحْمَةَ الَّذِي صَنَعَهَا».",
      "chapter": 11,
      "verse": 46
    }
  ]
}
